function myPromiseAll<T extends readonly unknown[] | []>(promises: T): Promise<{ -readonly [P in keyof T]: Awaited<T[P]> }> {
  return new Promise((resolve, reject) => {
    const arr = Array.from(promises);
    if (arr.length === 0) return resolve([] as any);
    const out: unknown[] = [];
    let n = 0;
    arr.forEach((p, i) => Promise.resolve(p).then(v => { out[i] = v; if (++n === arr.length) resolve(out as any); }, reject));
  });
}
